create or replace function public.admin_reject_event(p_event_id uuid,p_reason text) returns void language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); begin if not exists(select 1 from public.platform_admins where user_id=uid and is_active) then raise exception 'Platform admin access required'; end if; if p_reason is null or char_length(btrim(p_reason))<5 then raise exception 'A rejection reason is required'; end if; update public.events set status='draft',admin_approved=false,updated_at=now() where id=p_event_id and status='pending_review'; if not found then raise exception 'Event is not awaiting review'; end if; insert into public.event_notices(event_id,kind,message) values(p_event_id,'review','Platform review requested changes: '||p_reason); insert into public.admin_audit_log(admin_user_id,action,target_type,target_id,note) values(uid,'reject_event','event',p_event_id,p_reason); insert into public.notifications(user_id,organization_id,kind,title,body) select m.user_id,e.organization_id,'event_review','Event needs changes','Your event was returned for changes: '||p_reason from public.events e join public.organization_members m on m.organization_id=e.organization_id where e.id=p_event_id; end $$;
